var i=[{title:`Що записувати`,text:`Для силової роботи занотуйте вправу, варіацію, навантаження, повторення та завершені підходи, а також відпочинок, коли це важливо. Для вправ на час занотуйте тривалість і те, наскільки добре ви тримали положення. Для кондиції занотуйте активність, тривалість і відстань чи темп. Швидкий RPE заняття та короткий коментар можуть пояснити незвичний результат.`},{title:`Робіть записи порівнюваними`,text:`«Віджимання 10 повторень» важко читати, якщо висота рук чи амплітуда змінюється щоразу. Записуйте варіацію та умови, щоб порівнювати подібне з подібним. Тримайте все просто: кілька полів, які ви заповнюєте щоразу, краще за довгу форму, яку ви кидаєте.`},{title:`Додавайте нотатки для контексту`,text:`Поганий сон, незнайоме обладнання, перерви чи новий дискомфорт можуть пояснити слабше заняття. Один поганий день не є причиною перебудовувати всю програму. Тенденції за кілька занять показують, чи план стає надто легким, надто важким чи є приблизно правильним.`},{title:`Приклад`,text:`Тиждень перший: кубковий присід, 3 × 8 із 12 кг, помірне зусилля. Тиждень третій: 3 × 10 з тим самим навантаженням із хорошою технікою. Це вимірюване покращення, навіть якщо вага вашого тіла не змінилася.`},{title:`Як це працює в TrainUp`,text:`Під час тренування ви відмічаєте кожен підхід і записуєте повторення. Після нього оцінюєте зусилля заняття, повідомляєте про будь-який біль і додаєте нотатки. Історія показує цей тиждень, ваші загальні тренування, середнє зусилля та графік за 4 тижні, а завершені тренування ніколи не змінюються. Ваш план змінюється лише тоді, коли ви його перегенеровуєте.`}];var l=[{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Практичні рекомендації ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var n={sections:i,sources:l};export{n as default,i as sections,l as sources};